"use client";
import {useState} from "react";
import Link from "next/link";
const pages=[
 {id:"overview",label:"Overview",title:"Know what needs attention",text:"See requests waiting for your response and the next steps in your supplier setup."},
 {id:"products",label:"Products",title:"Manage your range without a spreadsheet",text:"Add products, photos, prices and stock. Drafts need review before publication."},
 {id:"requests",label:"Requests",title:"Respond to the right items and dates",text:"Review delivery and return dates per item. Confirm selected items, or explain what is unavailable and suggest alternatives to Styled."},
 {id:"business",label:"Business setup",title:"Explain how your business works",text:"Record service areas, delivery and collection options and your own hire policies. Optional details stay out of the way until needed."},
];
export default function SupplierTour(){const [active,setActive]=useState(pages[0]);return <section className="py-10 sm:py-14"><Link href="/business" className="inline-flex min-h-11 items-center text-sm underline">← For businesses</Link><p className="mt-4 text-sm font-medium uppercase tracking-widest text-clay">Supplier workspace tour</p><h1 className="mt-3 max-w-2xl font-serif text-4xl sm:text-5xl">Explore the supplier workspace</h1><p className="mt-4 max-w-2xl text-sm leading-relaxed text-ink/65">Example workspace. Nothing is saved or booked.</p><nav aria-label="Supplier tour sections" className="mt-7 flex flex-wrap gap-2">{pages.map(p=><button key={p.id} onClick={()=>setActive(p)} aria-pressed={active.id===p.id} className={`min-h-11 rounded-full px-5 py-3 text-sm ${active.id===p.id?"bg-ink text-cream":"border border-sand bg-white"}`}>{p.label}</button>)}</nav><div className="mt-7 max-w-2xl"><h2 className="font-serif text-2xl">{active.title}</h2><p className="mt-2 text-sm leading-relaxed text-ink/65">{active.text}</p></div><figure className="mt-5 overflow-hidden rounded-2xl border border-sand bg-white"><img src={`/img/supplier-tour/${active.id}.png`} alt={`Example supplier workspace: ${active.label}`} className="h-auto w-full"/><figcaption className="flex flex-wrap items-center justify-between gap-3 border-t border-sand px-5 py-3 text-sm text-ink/60"><span>Example workspace</span><a href={`/img/supplier-tour/${active.id}.png`} target="_blank" rel="noopener noreferrer" className="inline-flex min-h-11 items-center underline">Open full-size image ↗</a></figcaption></figure><div className="mt-7 flex flex-wrap gap-4"><Link href="/suppliers/join" className="min-h-11 rounded-full bg-ink px-6 py-3 text-sm text-cream">Apply to join</Link><Link href="/portal/login" className="inline-flex min-h-11 items-center text-sm underline">Already linked? Open your workspace →</Link></div></section>;}
